from compressor.semantic import compress_text, count_tokens
import gradio as gr
import time

async def predict(text, word_reduction_factor, reference_text_steering):
    if len(text.split()) > 10000:
        return "Text is too long for this demo. Please provide a text with less than 10000 words."

    if word_reduction_factor is None:
        word_reduction_factor = 0.5

    start = time.perf_counter()
    compressed = compress_text(text, compression_rate= word_reduction_factor, reference_text_steering=reference_text_steering)
    elapsed_ms = (time.perf_counter() - start) * 1000
    perc_reduction = round(100 - (count_tokens(compressed) / count_tokens(text)) * 100, 2)

    return f"{compressed}\n\nToken Reduction: {perc_reduction}% | Compressed in {elapsed_ms:.1f} ms on CPU"

SWEDEN_EN = 'Almost 30 years ago, a revolutionary idea changed the way Europe regarded road collisions. It has probably saved countless lives but it\'s yet to be fully accepted by politicians.  In 1995, a serious crash occurred on the E4 motorway near Stockholm, Sweden. Five young people were travelling in a hatchback car when the vehicle went into a roll near the exit ramp for the Ikea store. The car smashed into a concrete structure supporting a streetlight by the side of the road, and all five passengers were killed.  "I am rather sure they were speeding, and as it was wet, they probably aquaplaned," says Claes Tingvall. Almost 30 years on, he struggles to remember all the details – but he is sure about one thing: "The car was a three-door Peugeot 205 GTI, red."   More than 500 people died on Sweden\'s roads that year, but this tragedy signalled a turning point in how Tingvall, and eventually the world, regarded road  crashes. An estimated 1.2 million lives are cut short by road traffic collisions globally each year, while millions more suffer often life-changing injuries. While the death toll has decreased slightly over the past 13 years – the number of fatalities on the world\'s roads are 5% lower than they were in 2010 according to the World Health Organization (WHO) – progress has been slow and falls far short of the WHO\'s target of halving the number of road deaths by the end of this decade.  Today, Sweden has some of the lowest rates of road traffic fatalities in the world, and the story of how the country has strived to bring that number to zero provides a lesson for other countries where the death toll has remained stubbornly high.  Back in 1995, Tingvall had become the head of road safety for the Swedish Road Adminstration. He was very well qualified for the role, but quite unlike any of his predecessors. Instead of coming up through the ranks of road transport engineers and bureaucrats, Tingvall had a medical background: he had studied at the renowned Karolinska Institute, where he had gained a doctorate in the epidemiology of injuries.'

